package com.zafiro.wxentry.kernel;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.text.InputFilter;
import android.view.*;
import android.widget.*;
import java.lang.ref.WeakReference;
import java.text.SimpleDateFormat;
import java.util.*;

/** VIP task editor. Saving explicitly authorizes future publication of these exact contents. */
final class SnsScheduleUi {
    static WeakReference<AlertDialog> manager=new WeakReference<AlertDialog>(null);
    static final int PICK=0x6d58;static Editor picker;static final Set<Editor> editors=Collections.newSetFromMap(new WeakHashMap<Editor,Boolean>());
    static String time(long value){return new SimpleDateFormat("MM-dd HH:mm",Locale.getDefault()).format(new Date(value));}
    static String state(SnsScheduleData.State s){switch(s){case WAITING:return "待定时发布";case MISSED:return "待确认补发";case CLAIMED:return "正在提交";case UPLOADING:return "微信上传中";case PUBLISHED:return "已发布";case FAILED:return "失败（不自动重试）";case UNKNOWN:return "结果待核对（不自动重发）";default:return "已取消";}}
    static Set<String> editing(){Set<String> ids=new HashSet<String>();synchronized(editors){for(Editor e:editors)if(!e.done){ids.add(e.id);if(e.before!=null)ids.add(e.before.id);}}return ids;}
    static boolean allowed(Activity a,String owner){if(SnsScheduleRuntime.authorized(owner))return true;toast(a,"定时朋友圈仅限当前已激活的 VIP 账号");return false;}
    static void toast(Context c,String text){Toast.makeText(c,text,Toast.LENGTH_LONG).show();}
    static void button(LinearLayout box,String text,final Runnable action){Button b=new Button(box.getContext());b.setText(text);box.addView(b);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){action.run();}});}
    static ScrollView scroll(Activity a,LinearLayout box){ScrollView s=new ScrollView(a);s.addView(box);return s;}
    static void show(final Activity a){
        final String owner=Kernel.receiptAccount();if(!allowed(a,owner))return;
        try{AlertDialog previous=manager.get();if(previous!=null&&previous.isShowing())previous.dismiss();final SnsScheduleData data=SnsScheduleStore.load(owner);LinearLayout box=SettingsUi.column(a);
            box.addView(SettingsUi.toggle(a,"定时自动发朋友圈","仅当前账号 · 关闭后未提交任务暂停；已交给微信的上传不能撤回",data.enabled,new SettingsUi.Change(){public boolean set(final boolean on){boolean okay=SnsScheduleStore.edit(owner,new SnsScheduleStore.Edit(){public void apply(SnsScheduleData d){d.enabled=on;}});if(!okay)toast(a,"设置保存失败");SnsScheduleRuntime.changed();return okay?on:!on;}}));
            box.addView(SettingsUi.text(a,"支持文字和最多 9 张图片。请保持微信运行及网络可用；停止运行或错过计划时间后，只提醒，由你确认补发。\n按手机本地时间执行，任务内显示时区。任务绑定当前账号，切换账号不会代发。",13));
            box.addView(SettingsUi.text(a,"息屏时会在计划前约 2 秒尝试唤醒 CPU，短时执行后台发送，屏幕保持关闭。请勿强制停止微信；进程被杀或错过时间后需确认补发。",13));
            if(!SnsScheduleWake.exactAllowed())button(box,"允许息屏准时执行（系统设置）",new Runnable(){public void run(){SnsScheduleWake.permission(a);}});
            if(!SnsScheduleRuntime.nativeError.isEmpty())box.addView(SettingsUi.text(a,SnsScheduleRuntime.nativeError,14));
            button(box,"新建定时图文",new Runnable(){public void run(){if(!SnsScheduleRuntime.nativeError.isEmpty()){toast(a,SnsScheduleRuntime.nativeError);return;}new Editor(a,owner,null).show();}});
            List<SnsScheduleData.Task> tasks=new ArrayList<SnsScheduleData.Task>(data.tasks);Collections.sort(tasks,new Comparator<SnsScheduleData.Task>(){public int compare(SnsScheduleData.Task x,SnsScheduleData.Task y){return Long.compare(y.created,x.created);}});
            if(tasks.isEmpty())box.addView(SettingsUi.text(a,"暂无定时任务",15));for(final SnsScheduleData.Task t:tasks)button(box,time(t.due)+" · "+state(t.state)+"\n"+(t.text.isEmpty()?"[图文]":t.text.substring(0,Math.min(28,t.text.length())))+" · "+t.photos.size()+" 张图",new Runnable(){public void run(){detail(a,owner,t.id);}});
            AlertDialog current=new AlertDialog.Builder(a).setTitle("定时发朋友圈（VIP）").setView(scroll(a,box)).setPositiveButton("关闭",null).setNeutralButton("刷新",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){show(a);}}).show();manager=new WeakReference<AlertDialog>(current);
        }catch(Throwable e){SnsScheduleRuntime.log("manager-failed",e);toast(a,"任务文件读取失败，已停止自动发布，请保留文件并上报自检");}
    }
    static void detail(final Activity a,final String owner,final String id){
        if(!allowed(a,owner))return;try{final SnsScheduleData.Task t=SnsScheduleStore.load(owner).find(id);if(t==null)return;LinearLayout box=SettingsUi.column(a);
            box.addView(SettingsUi.text(a,state(t.state)+"\n计划时间："+time(t.due)+" ("+TimeZone.getDefault().getID()+")\n可见范围："+(t.selfOnly?"仅自己可见":"公开")+"\n"+t.message+"\n\n"+t.text,15));
            for(SnsScheduleData.Photo p:t.photos){if(!SnsScheduleMedia.path(t,p).isFile())continue;ImageView img=new ImageView(a);android.graphics.BitmapFactory.Options opt=new android.graphics.BitmapFactory.Options();opt.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(SnsScheduleMedia.path(t,p).getPath(),opt);int sample=1;while(opt.outWidth/sample>512||opt.outHeight/sample>512)sample*=2;opt.inSampleSize=sample;opt.inJustDecodeBounds=false;android.graphics.Bitmap b=android.graphics.BitmapFactory.decodeFile(SnsScheduleMedia.path(t,p).getPath(),opt);if(b!=null)img.setImageBitmap(b);img.setAdjustViewBounds(true);img.setMaxHeight(SettingsUi.dp(a,150));box.addView(img,new LinearLayout.LayoutParams(-1,SettingsUi.dp(a,150)));}
            final AlertDialog dlg=new AlertDialog.Builder(a).setTitle("任务详情 · "+t.photos.size()+" 张图").setView(scroll(a,box)).setNegativeButton("关闭",null).create();
            if(t.state==SnsScheduleData.State.MISSED)button(box,"确认补发",new Runnable(){public void run(){new AlertDialog.Builder(a).setTitle("确认立即补发？").setMessage("将按已保存的文字、"+t.photos.size()+" 张图片及可见范围立即提交一次。请先核对自己的朋友圈，确认此前未发布。").setNegativeButton("取消",null).setPositiveButton("确认补发",new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int w){if(!allowed(a,owner))return;boolean okay=SnsScheduleRuntime.launch(id,true);toast(a,okay?"正在准备补发，请稍后刷新任务结果":"任务状态已变化或权限不可用，请刷新");dlg.dismiss();}}).show();}});
            if(t.editable())button(box,"编辑内容与时间",new Runnable(){public void run(){dlg.dismiss();new Editor(a,owner,t).show();}});
            if(t.editable())button(box,"取消任务",new Runnable(){public void run(){boolean okay=SnsScheduleStore.edit(owner,new SnsScheduleStore.Edit(){public void apply(SnsScheduleData d){SnsScheduleData.Task task=d.find(id);if(task==null||!task.editable())throw new IllegalStateException();task.state=SnsScheduleData.State.CANCELLED;task.message="已取消";task.updated=System.currentTimeMillis();}});if(okay){SnsScheduleMedia.clean(owner,id);SnsScheduleRuntime.changed();dlg.dismiss();}toast(a,okay?"已取消，模块图片副本已清理":"任务已提交或取消失败，请刷新");}});
            if(!t.active())button(box,"删除任务记录",new Runnable(){public void run(){boolean okay=SnsScheduleStore.edit(owner,new SnsScheduleStore.Edit(){public void apply(SnsScheduleData d){SnsScheduleData.Task task=d.find(id);if(task==null||task.active())throw new IllegalStateException();d.tasks.remove(task);}});if(okay){SnsScheduleMedia.clean(owner,id);dlg.dismiss();}toast(a,okay?"已删除模块任务记录（已发朋友圈请在微信删除）":"删除失败");}});
            dlg.show();
        }catch(Throwable e){SnsScheduleRuntime.log("detail-failed",e);toast(a,"任务读取失败");}
    }
    static final class Editor {
        final WeakReference<Activity> activity;final String owner,id;final SnsScheduleData.Task before;final List<SnsScheduleData.Photo> photos=new ArrayList<SnsScheduleData.Photo>();final Calendar due=Calendar.getInstance();
        EditText content;TextView dateLabel,photoLabel;Spinner visibility;AlertDialog dialog;boolean importing,done,saved;String photoId;
        Editor(Activity a,String owner,SnsScheduleData.Task before){activity=new WeakReference<Activity>(a);this.owner=owner;this.before=before;id=UUID.randomUUID().toString().replace("-","");photoId=id;if(before!=null){due.setTimeInMillis(before.due);photos.addAll(before.photos);photoId=before.id;}else{due.add(Calendar.MINUTE,5);due.set(Calendar.SECOND,0);due.set(Calendar.MILLISECOND,0);}synchronized(editors){editors.add(this);}}
        void show(){final Activity a=activity.get();if(a==null||!allowed(a,owner)){done=true;return;}if(before!=null)try{SnsScheduleData.Task current=SnsScheduleStore.load(owner).find(before.id);if(current==null||!current.editable()){done=true;toast(a,"原任务已提交，不能继续编辑");return;}}catch(Throwable e){done=true;toast(a,"任务状态读取失败");return;}LinearLayout box=SettingsUi.column(a);box.addView(SettingsUi.text(a,"保存后，到计划时间会自动发布。请核对文字、图片顺序和可见范围。编辑期间若到点，原任务会等待确认，不会发出旧内容。",14));content=new EditText(a);content.setHint("编辑朋友圈内容（可留空只发图片）");content.setMinLines(3);content.setMaxLines(7);content.setFilters(new InputFilter[]{new InputFilter.LengthFilter(SnsScheduleData.MAX_TEXT)});if(before!=null)content.setText(before.text);box.addView(content);
            photoLabel=SettingsUi.text(a,"",14);box.addView(photoLabel);updatePhotos();button(box,"选择 / 替换图片（最多 9 张，按选择器返回顺序）",new Runnable(){public void run(){pick();}});button(box,"清空图片",new Runnable(){public void run(){if(importing)return;if(photoId.equals(id))SnsScheduleMedia.clean(owner,id);photos.clear();photoId=id;updatePhotos();}});
            visibility=new Spinner(a);visibility.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"公开（所有好友）","仅自己可见"}));visibility.setSelection(before!=null&&before.selfOnly?1:0);box.addView(visibility);
            dateLabel=SettingsUi.text(a,"",15);box.addView(dateLabel);updateTime();button(box,"设置日期",new Runnable(){public void run(){new DatePickerDialog(a,new DatePickerDialog.OnDateSetListener(){public void onDateSet(DatePicker p,int y,int m,int d){due.set(y,m,d);updateTime();}},due.get(Calendar.YEAR),due.get(Calendar.MONTH),due.get(Calendar.DAY_OF_MONTH)).show();}});button(box,"设置时间",new Runnable(){public void run(){new TimePickerDialog(a,new TimePickerDialog.OnTimeSetListener(){public void onTimeSet(TimePicker p,int h,int m){due.set(Calendar.HOUR_OF_DAY,h);due.set(Calendar.MINUTE,m);due.set(Calendar.SECOND,0);due.set(Calendar.MILLISECOND,0);updateTime();}},due.get(Calendar.HOUR_OF_DAY),due.get(Calendar.MINUTE),true).show();}});
            dialog=new AlertDialog.Builder(a).setTitle(before==null?"新建定时图文":"编辑定时图文").setView(scroll(a,box)).setNegativeButton("取消",null).setPositiveButton("保存并开启定时发布",null).create();dialog.setOnDismissListener(new DialogInterface.OnDismissListener(){public void onDismiss(DialogInterface d){done=true;if(!saved&&!importing)SnsScheduleMedia.clean(owner,id);SnsScheduleRuntime.changed();}});dialog.show();dialog.getButton(-1).setOnClickListener(new View.OnClickListener(){public void onClick(View v){save();}});
        }
        void updateTime(){dateLabel.setText("计划："+new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.getDefault()).format(due.getTime())+"\n时区："+TimeZone.getDefault().getID());}
        void updatePhotos(){photoLabel.setText(importing?"正在复制图片…":"已选 "+photos.size()+" 张图片（保存独立副本）");}
        void pick(){Activity a=activity.get();if(a==null||done||importing||!allowed(a,owner))return;if(picker!=null&&(picker.done||picker.activity.get()==null))picker=null;if(picker!=null){toast(a,"请先完成当前图片选择");return;}try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);picker=this;a.startActivityForResult(i,PICK);}catch(Throwable e){picker=null;toast(a,"系统图片选择器不可用");}}
        void selected(final List<Uri> uris){final Activity a=activity.get();if(a==null||done||uris.isEmpty())return;if(uris.size()>9){toast(a,"最多选择 9 张图片");return;}importing=true;updatePhotos();SnsScheduleRuntime.io.execute(new Runnable(){public void run(){try{SnsScheduleMedia.clean(owner,id);final List<SnsScheduleData.Photo> result=SnsScheduleMedia.importPhotos(a.getApplicationContext(),owner,id,uris);SnsScheduleRuntime.main.post(new Runnable(){public void run(){importing=false;if(done||!allowed(a,owner)){SnsScheduleMedia.clean(owner,id);return;}photoId=id;photos.clear();photos.addAll(result);updatePhotos();}});}catch(final Throwable e){SnsScheduleRuntime.main.post(new Runnable(){public void run(){importing=false;SnsScheduleRuntime.log("image-import-failed",e);if(!done){toast(a,e.getMessage()==null?"图片复制失败":e.getMessage());updatePhotos();}else SnsScheduleMedia.clean(owner,id);}});}}});}
        void save(){final Activity a=activity.get();if(a==null||done||importing||!allowed(a,owner))return;final long now=System.currentTimeMillis();if(due.getTimeInMillis()<now+15000){toast(a,"请设置至少 15 秒后的时间");return;}if(due.getTimeInMillis()>now+366L*24*60*60*1000){toast(a,"请设置一年内的时间");return;}if(content.getText().toString().trim().isEmpty()&&photos.isEmpty()){toast(a,"请填写文字或选择图片");return;}
            final SnsScheduleData.Task task=new SnsScheduleData.Task(id,owner,content.getText().toString(),due.getTimeInMillis(),visibility.getSelectedItemPosition()==1,now);task.photos.addAll(photos);
            try{
                if(!photoId.equals(id)&&!photos.isEmpty()){SnsScheduleData.Task src=before;SnsScheduleMedia.verify(src);long additional=0;for(SnsScheduleData.Photo p:photos)additional+=p.size;if(SnsScheduleMedia.size(SnsScheduleStore.root())+additional>SnsScheduleMedia.MAX_CACHE)throw new java.io.IOException("图片缓存空间不足");java.io.File folder=SnsScheduleMedia.dir(owner,id);folder.mkdirs();for(SnsScheduleData.Photo p:photos){java.io.File f=SnsScheduleStore.child(folder,p.name);try(java.io.InputStream in=new java.io.FileInputStream(SnsScheduleMedia.path(src,p));java.io.FileOutputStream out=new java.io.FileOutputStream(f)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.getFD().sync();}}photoId=id;}
                SnsScheduleMedia.verify(task);boolean okay=SnsScheduleStore.edit(owner,new SnsScheduleStore.Edit(){public void apply(SnsScheduleData d){if(before!=null){SnsScheduleData.Task old=d.find(before.id);if(old==null||!old.editable())throw new IllegalStateException("原任务已经提交");d.tasks.remove(old);}int n=0;for(SnsScheduleData.Task t:d.tasks)if(t.active())n++;if(n>=SnsScheduleData.MAX_ACTIVE)throw new IllegalArgumentException("待处理任务过多");while(d.tasks.size()>=SnsScheduleData.MAX_TASKS){SnsScheduleData.Task remove=null;for(SnsScheduleData.Task t:d.tasks)if(!t.active()){remove=t;break;}if(remove==null)throw new IllegalArgumentException();d.tasks.remove(remove);}d.tasks.add(task);d.enabled=true;}});
                if(!okay){toast(a,"任务保存失败，请检查任务数量及权限");return;}saved=true;if(before!=null)SnsScheduleMedia.clean(owner,before.id);dialog.dismiss();SnsScheduleRuntime.changed();SnsScheduleUi.show(a);toast(a,"定时任务已保存并开启，"+photos.size()+" 张图片 · "+(task.selfOnly?"仅自己可见":"公开"));
            }catch(Throwable e){SnsScheduleRuntime.log("draft-save-failed",e);toast(a,"图片保存失败，请重新选择图片");}
        }
    }
    static boolean picked(Activity a,int result,Intent data){final Editor e=picker;if(e==null||e.activity.get()!=a)return false;picker=null;if(result!=Activity.RESULT_OK||data==null)return true;List<Uri> uris=new ArrayList<Uri>();ClipData clips=data.getClipData();if(clips!=null){if(clips.getItemCount()>9){toast(a,"最多选择 9 张图片");return true;}for(int i=0;i<clips.getItemCount();i++)uris.add(clips.getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());e.selected(uris);return true;}
}
